import {JKS,SIZES,PEOPLE,EVENT_DATE,feeFor,zoneFor,money,digits,uid,isComplete,statusFor,createInitialState,scopedRows,aggregate,validatePeople,paymentTotals,commitGroup,collectPayment,publicPerson} from './model.mjs';
const $=s=>document.querySelector(s), KEY='ivc26-demo-v1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageProblem='';
function readState(){try{const s=JSON.parse(localStorage.getItem(KEY));return s?.version===1?s:createInitialState();}catch{return createInitialState();}}
let state=readState(),session;try{session=JSON.parse(sessionStorage.getItem('ivc-session'));}catch{}
let demoDate=sessionStorage.getItem('ivc-date')||'2026-11-06';
const ui={search:'',results:null,selected:[],draft:[],step:0,current:0,cash:'',confirmation:[],filter:'All statuses',listSearch:'',reportJk:'All JKs',closeJk:'Dallas HQ',closeDate:demoDate,denied:false,loading:false,error:'',custom:[]};
const ACCOUNTS=[{name:'Rehana',role:'admin',label:'JK admin',jk:'Dallas HQ',email:'rehana.admin@example.com'},{name:'Saira',role:'desk',label:'Desk volunteer',jk:'Dallas HQ',email:'saira.desk@example.com'},{name:'Azim',role:'super',label:'Super admin',jk:'Dallas HQ',email:'azim.region@example.com'},{name:'Unapproved account',role:'denied',label:'Access test',jk:'Dallas HQ',email:'not.approved@example.com'}];
const ICONS={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',desk:'<path d="M4 20V8h16v12M2 8h20M8 8V4h8v4M8 20v-5h8v5"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M22 21v-2a4 4 0 0 0-3-3.87"/><circle cx="9" cy="7" r="4"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/>',chart:'<path d="M4 3v17h17M8 16v-5m5 5V6m5 10v-8"/>',wallet:'<path d="M20 8V5H5a3 3 0 0 0 0 6h16v8H5a3 3 0 0 1-3-3V8m14 6h5"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',check:'<path d="m5 12 4 4L19 6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',shirt:'<path d="m8 3-6 4 3 5 3-2v11h8V10l3 2 3-5-6-4c0 4-8 4-8 0Z"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',external:'<path d="M14 3h7v7m-1-6L10 14M11 3H4v17h17v-7"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',plus:'<path d="M12 5v14M5 12h14"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',heart:'<path d="M20 4c-3-2-6 0-8 3-2-3-5-5-8-3-5 4 0 10 8 17 8-7 13-13 8-17Z"/>',logout:'<path d="M9 4H4v16h5m5-4 4-4-4-4M8 12h13"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[n]||ICONS.check}</svg>`;
const btn=(label,action,cls='button',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const badge=(text,kind='neutral')=>`<span class="badge ${kind}">${esc(text)}</span>`;
const statusBadge=r=>badge(statusFor(r),isComplete(r)?'success':'warning');
const options=(items,value)=>items.map(v=>`<option ${v===value?'selected':''}>${esc(v)}</option>`).join('');
const field=(label,name,value='',extra='',type='text')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select=(label,name,items,value='',extra='')=>`<label class="field"><span>${label}</span><select name="${name}" ${extra}>${options(items,value)}</select></label>`;
const logo=(cls='')=>`<img class="event-logo ${cls}" src="./assets/ivc-logo-background.svg" alt="Ismaili Volunteers Celebration of Service 2026 emblem">`;
const dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
const phone=p=>digits(p).replace(/(\d{3})(\d{3})(\d{4})/,'($1) $2-$3');
function ctx(){return{...session,date:demoDate,time:new Date().toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit',timeZone:'America/Chicago'}),actor:session?.name+' · '+session?.label};}
function persist(next=state){try{localStorage.setItem(KEY,JSON.stringify(next));state=next;storageProblem='';return true;}catch{storageProblem='This browser could not save changes. Keep this tab open and allow browser storage before trying again.';toast(storageProblem);return false;}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function nav(route){location.hash=route;ui.error='';if(location.hash.slice(1)===route)render();}
function pack(obj){return btoa(unescape(encodeURIComponent(JSON.stringify(obj))));}
function unpack(s){try{return JSON.parse(decodeURIComponent(escape(atob(s))));}catch{return null;}}
function linkFor(type,r){const p=publicPerson(r);return location.href.split('#')[0]+'#'+type+'/'+pack(p);}
function qrHTML(url){try{const q=window.qrcode(0,'M');q.addData(url);q.make();return q.createSvgTag({cellSize:3,margin:4,scalable:true});}catch{return'<span>QR unavailable. Use the personal link below.</span>';}}
const directions='https://www.google.com/maps/search/?api=1&query=Plano+Sports+Authority+2+601+Seabrook+Dr+Plano+TX+75023';
const demoNotice='<span class="demo-dot"></span> Prototype · fake data only';
function publicHeader(){return `<header class="public-header"><a href="#event" class="wordmark"><span class="mark">IVC</span><span>Celebration of Service<small>CENTRAL USA · 2026</small></span></a><a class="text-link" href="#desk">Registration desk ${icon('arrow')}</a></header><div class="public-demo">${demoNotice}</div>`;}
function errorBox(){return ui.error?`<div class="notice error" role="alert">${esc(ui.error)}</div>`:'';}
function shell(content,route){const allowed=session.role!=='desk';const scope=session.role==='super'?'Central Region':session.jk;return `<div class="app-shell"><aside class="sidebar"><a class="brand" href="#desk"><span class="brand-year">IVC <b>2026</b></span><span>Celebration of Service</span><small>CENTRAL USA</small></a><div class="nav-label">REGISTRATION</div><nav aria-label="Desk navigation">${[['desk','desk','Registration desk'],['registrations','users','Registrations'],...(allowed?[['reports','chart','Reports'],['close','wallet','Cash close']]:[])].map(([r,i,t])=>`<a href="#${r}" class="nav-link ${route===r?'active':''}" ${route===r?'aria-current="page"':''}>${icon(i)}${t}${r==='registrations'?`<span class="nav-count">${scopedRows(state,ctx()).length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-event">${logo()}<p>Sunday, November 22</p><span>9 AM – 3 PM · Plano, TX</span><a href="#event">View event page ${icon('external')}</a></div><div class="account"><span class="avatar">${esc(session.name[0])}</span><span><b>${esc(session.name)}</b><small>${esc(session.label)}</small></span>${btn(icon('logout'),'signout','icon-button','aria-label="Sign out"')}</div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">Central USA <span>/</span> <b>${esc(scope)}</b></div><div class="topbar-right"><span class="demo-label">${demoNotice}</span>${btn('Demo controls','demo-controls','button small secondary')}</div></header><main id="main" class="main-content">${storageProblem?`<div class="notice error" role="alert">${esc(storageProblem)}</div>`:''}${content}</main><footer class="desk-footer"><span>IVC 2026 · Every volunteer, one personal ticket.</span><span>${esc(session.jk)} desk · ${dateLabel(demoDate)}</span></footer></div></div>`;}
function titleBlock(kicker,title,desc='',right=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>${right}</div>`;}
function loginView(){return `<div class="login"><section class="login-story"><div class="login-brand">IVC <span>2026</span></div>${logo('login-emblem')}<div><div class="eyebrow">CENTRAL USA</div><h1>Celebration<br>of Service.</h1><p>Sunday, November 22, 2026<br>9 AM – 3 PM · Plano Sports Authority 2</p></div><small>ISMAILI VOLUNTEERS</small></section><main id="main" class="login-main"><div class="login-form"><span class="demo-label">${demoNotice}</span><div class="eyebrow">THE REGISTRATION DESK</div><h2>A warm welcome<br>starts here.</h2><p>Sign in with an approved desk account to register volunteers and their families.</p>${ui.denied?'<div class="notice error" role="alert"><b>This account isn’t approved.</b><br>Only approved desk accounts can access registration. Choose a different demo account.</div>':''}<form data-form="login"><label class="field"><span>Demo account</span><select name="account">${ACCOUNTS.map((a,i)=>`<option value="${i}">${a.name} - ${a.label}</option>`).join('')}</select></label><button class="button google full" type="submit"><span class="google-g" aria-hidden="true">G</span>Continue with Google <span class="subtle">(demo)</span>${icon('arrow')}</button></form><div class="login-note">${icon('shield')}<p>This demo uses fictional accounts. It won’t connect to Google or send messages.</p></div><a class="text-link" href="#event">Explore the public event page ${icon('arrow')}</a></div><span class="login-bottom">11 Jamatkhanas. One celebration of service.</span></main></div>`;}
const scenarios=[['Single adult','2145550101','One volunteer, one ticket'],['Family of three','2145550102','Guardian + two children'],['Parent away','2145550103','17-year-old · waiver link'],['Affordability','2145550104','Approve support at the desk'],['Donation','2145550105','Cash overpayment'],['COC needed','2145550106','Record completion at desk'],['Inactive volunteer','2145550107','Facilitator confirmation'],['Pre-covered','2145550108','Support already noted'],['No match','2145550190','Staff-verified entry']];
function getPeople(){const found=new Map([...PEOPLE,...ui.custom].map(p=>[p.id,{...p,...state.overrides[p.id]}]));for(const r of state.registrations){found.set(r.personId,{...(found.get(r.personId)||{}),...r,id:r.personId});}return [...found.values()];}
function personCard(p){const existing=state.registrations.find(r=>r.personId===p.id),own=!existing||session.role==='super'||existing.deskJk===session.jk;return `<div class="person-result ${ui.selected.includes(p.id)?'selected':''} ${p.guardian?'guardian-row':''}"><div class="person-main">${existing?'':`<input type="checkbox" aria-label="Select ${esc(p.name)}" data-person="${p.id}" ${ui.selected.includes(p.id)?'checked':''}>`}<span class="person-avatar">${esc(p.name.split(' ').map(s=>s[0]).slice(0,2).join(''))}</span><div><h3>${esc(p.name)} ${p.guardian?badge('Guardian','blue'):''}</h3><p>${p.age} years · ${esc(p.jk)} · ${phone(p.phone)}</p></div>${existing?(own?btn('Open registration','record','button small secondary',`data-id="${existing.id}"`):badge('Registered at another desk')):''}</div><div class="person-status">${existing?(own?statusBadge(existing):'<span class="subtle">Ask a super admin for help with this existing registration.</span>'):p.guardian?'<span class="subtle">Active status and COC not required for accompanying guardians</span>':`${badge(p.active?'Active volunteer':'Inactive',p.active?'success':'warning')}${badge(p.coc?'COC complete':'COC needed',p.coc?'success':'warning')}${!p.active?btn('Confirm with facilitator','eligibility','text-button',`data-id="${p.id}" data-kind="active"`):''}${!p.coc?btn('Record COC completion','eligibility','text-button',`data-id="${p.id}" data-kind="coc"`):''}`}</div></div>`;}
function deskView(){if(ui.confirmation.length)return confirmationView();if(ui.step)return wizardView();const rows=scopedRows(state,ctx()),today=rows.filter(r=>r.date===demoDate).length;return `${titleBlock('REGISTRATION DESK','Welcome to the desk.','Find a volunteer to begin their registration.',`<div class="fee-card"><span>${demoDate<='2026-11-06'?'EARLY REGISTRATION':'STANDARD REGISTRATION'}</span><strong>${money(feeFor(demoDate)).replace('.00','')}<small>/ person</small></strong><p>T-shirt included · ${dateLabel(demoDate)}</p></div>`)}<div class="desk-grid"><section><div class="panel search-panel"><div class="section-heading"><span class="step-circle">1</span><div><h2>Find a volunteer</h2><p>Use the phone number in their volunteer record.</p></div></div><form data-form="search" class="search-form"><label class="field"><span>Phone number</span><div class="input-icon">${icon('search')}<input name="phone" type="tel" inputmode="tel" autocomplete="off" placeholder="(214) 555-0101" value="${esc(ui.search)}" required aria-describedby="phone-help"></div></label><button class="button" type="submit">${ui.loading?'Searching…':'Find people'}${icon('arrow')}</button></form><small id="phone-help">Families may share the same phone number.</small>${errorBox()}</div>${ui.loading?'<div class="panel empty"><span class="spinner"></span><p>Searching demo records…</p></div>':ui.results!==null?`<div class="results-heading"><h2>${ui.results.length?`${ui.results.length} ${ui.results.length===1?'person':'people'} found`:'No matching records'}</h2>${ui.results.length?btn('Add a guardian','add-guardian','text-button'):''}</div>${ui.results.length?`<div class="result-list">${ui.results.map(personCard).join('')}</div><div class="selection-bar"><span><b>${ui.selected.length}</b> selected</span>${btn('Continue with selected '+icon('arrow'),'begin','button',ui.selected.length?'':'disabled')}</div>`:`<div class="panel empty">${icon('search')}<h3>No one found for ${phone(ui.search)}</h3><p>Check the number with the volunteer, or add a person for staff verification.</p><div class="button-row">${btn('Add person for verification','add-person','button')}${btn('Try another number','clear-search','button secondary')}</div></div>`}`:`<div class="desk-guidance"><div class="guidance-icon">${icon('users')}</div><div><h3>One family. Individual registrations.</h3><p>Select everyone attending. Each person receives their own waiver status, fee and ticket.</p></div></div>`}<details class="demo-scenarios" ${ui.results===null?'open':''}><summary>Try a demo scenario <span>9 sample situations</span></summary><div class="scenario-grid">${scenarios.map(([n,p,s])=>btn(`<b>${n}</b><span>${s}</span><small>${phone(p)}</small>`,'scenario','scenario',`data-phone="${p}"`)).join('')}</div></details></section><aside class="desk-aside"><div class="panel day-panel"><div class="eyebrow">YOUR DESK TODAY</div><h2>${esc(session.jk)}</h2><div class="day-number">${today}<span>new registrations</span></div><div class="stat-line"><span>Waiting on parent</span><b>${rows.filter(r=>statusFor(r)==='Waiting on parent').length}</b></div><div class="stat-line"><span>Payment pending</span><b>${rows.filter(r=>r.payment==='Pending').length}</b></div><a class="text-link" href="#registrations">View registrations ${icon('arrow')}</a></div><div class="desk-reminder"><span class="mini-label">BEFORE YOU BEGIN</span><div>${icon('shield')}<p>Active volunteer + completed Code of Conduct.</p></div><div>${icon('users')}<p>Ages 8–15 need one accompanying adult guardian.</p></div><div>${icon('shirt')}<p>Confirm a T-shirt size for every attendee.</p></div></div><div class="event-date-strip"><span>22<small>NOV</small></span><div>Sunday, 9 AM – 3 PM<small>Plano Sports Authority 2</small></div></div></aside></div>`;}
function draftSummary(){const total=ui.draft.reduce((s,p)=>s+p.fee,0);return `<aside class="panel draft-summary"><div class="eyebrow">THIS REGISTRATION</div><h2>${ui.draft.length} ${ui.draft.length===1?'attendee':'attendees'}</h2>${ui.draft.map((p,i)=>`<div class="summary-person"><span class="person-avatar small">${esc(p.name[0])}</span><div><b>${esc(p.name)}</b><small>${p.guardian?'Accompanying guardian':zoneFor(p.age)}</small></div><strong>${money(p.fee).replace('.00','')}</strong></div>`).join('')}<div class="summary-total"><span>Registration fees</span><strong>${money(total)}</strong></div><p class="subtle">One fee and one T-shirt per person. Payment is recorded individually.</p>${btn('Discard this draft','discard','text-button danger')}</aside>`;}
function wizardView(){return `${titleBlock('NEW REGISTRATION',ui.step===1?'A few details.':ui.step===2?'Parent permission.':'Collect payment.',ui.step===1?'Confirm the information for each person attending.':ui.step===2?'A parent signs for everyone under 18.':'Record each person’s payment, then count the cash.')}<ol class="stepper">${['People & details','Parent waiver','Cash payment'].map((s,i)=>`<li class="${ui.step===i+1?'current':ui.step>i+1?'done':''}"><span>${ui.step>i+1?icon('check'):i+1}</span>${s}</li>`).join('')}</ol>${errorBox()}<div class="wizard-grid"><section>${ui.step===1?detailsView():ui.step===2?waiverView():cashView()}</section>${draftSummary()}</div>`;}
function detailsView(){const p=ui.draft[ui.current],adults=ui.draft.filter(x=>x.age>=18&&x.id!==p.id);return `<form data-form="details" class="panel form-panel"><div class="form-title"><div><span class="eyebrow">PERSON ${ui.current+1} OF ${ui.draft.length}</span><h2>${esc(p.name)}</h2></div>${p.guardian?badge('Accompanying guardian','blue'):badge(zoneFor(p.age))}</div><div class="field-grid">${field('Full name','name',p.name,'required data-draft')}${field('Phone number','phone',phone(p.phone),'required inputmode="tel" data-draft','tel')}${field('Age at the event','age',p.age,'required min="8" max="90" step="1" data-draft','number')}${select('Home Jamatkhana','jk',JKS.filter(x=>x!=='Event-day desk'),p.jk,'data-draft')}${select('T-shirt size *','size',['Choose a size',...SIZES],p.size||'Choose a size','required data-draft')}${field('Email (optional)','email',p.email||'','data-draft','email')}</div><p class="field-help">Confirm their age on November 22, 2026. A birth year alone may be one year off.</p>${p.age<=15||p.age<18&&adults.some(x=>x.guardian)?`<div class="guardian-section"><h3>${icon('users')} Accompanying guardian</h3><p>${p.age<=15?'Ages 8–15 must be linked to exactly one adult.':'Link an accompanying guardian if one is registering with this teen.'}</p><label class="field"><span>Guardian ${p.age<=15?'*':'(optional)'}</span><select name="guardianId" data-draft ${p.age<=15?'required':''}><option value="">Choose an adult in this registration</option>${adults.map(g=>`<option value="${g.id}" ${p.guardianId===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}</select></label>${!adults.length?'<p class="inline-error">Go back and add an adult guardian before continuing.</p>':''}</div>`:''}<div class="form-divider"></div><h3>Emergency contact</h3><p class="subtle">Someone we can reach during the event.</p><div class="field-grid">${field('Contact name *','emergencyName',p.emergencyName||'','required data-draft')}${field('Contact phone *','emergencyPhone',phone(p.emergencyPhone||''),'required inputmode="tel" data-draft','tel')}</div><div class="form-actions">${btn('← Back',ui.current?'previous-person':'back-search','button secondary')}<button class="button" type="submit">${ui.current<ui.draft.length-1?'Save & next person':'Continue to waiver'}${icon('arrow')}</button></div>${ui.draft.length>1?btn('Remove this person from the draft','remove-person','text-button danger'):''}</form>`;}
const waiverText=`<div class="waiver-text"><span class="mini-label">SAMPLE WAIVER · NOT FINAL LEGAL TEXT</span><p>I am the parent or legal guardian of the child named here. I give permission for them to attend IVC 2026 and participate in event activities.</p><p>I understand that the final event waiver will replace this sample before real registration begins.</p></div>`;
function signatureFields(name='',prefix=''){return `<div class="signature-fields"><label class="field"><span>Parent / legal guardian full name *</span><input name="parentName" value="${esc(name)}" required autocomplete="off"></label><div class="signature-tabs" role="group" aria-label="Signature method">${btn('Type signature','signature-type','tab active')}${btn('Draw signature','signature-draw','tab')}</div><div class="typed-signature"><label class="field"><span>Type full name to sign *</span><input class="signature-input" name="signature" placeholder="Your full name" autocomplete="off"></label></div><div class="drawn-signature" hidden><canvas class="signature-canvas" width="560" height="150" aria-label="Draw your signature; use Type signature for keyboard entry"></canvas>${btn('Clear signature','clear-signature','text-button')}</div><label class="checkbox-line"><input type="checkbox" name="consent" required><span>I am this child’s parent or legal guardian and agree to the sample waiver.</span></label></div>`;}
function waiverView(){const minors=ui.draft.filter(p=>p.age<18);return `<div class="panel form-panel">${minors.length?`<h2>Waivers for ${minors.length} ${minors.length===1?'child':'children'}</h2><p class="subtle">Each child has a separate waiver record.</p>${minors.map(p=>`<div class="waiver-person"><div><span class="person-avatar">${esc(p.name[0])}</span><div><h3>${esc(p.name)}</h3><p>${p.age} years · ${esc(zoneFor(p.age))}</p></div></div><div>${badge(p.waiver||'Signature needed',p.waiver==='Signed'?'success':'warning')}${btn(p.waiver==='Signed'?'Review signature':'Parent is here','sign-child','button small secondary',`data-id="${p.id}"`)}${p.age>=16?btn('Parent is away','parent-away','text-button',`data-id="${p.id}"`):''}</div></div>`).join('')}<div class="notice">${icon('shield')}<p>Ages 8–15 must have their parent’s waiver completed at the desk. For ages 16–17, save a parent link and follow up later.</p></div>`:`<div class="empty compact">${icon('check')}<h2>No parent waiver needed</h2><p>Everyone in this registration is 18 or older.</p></div>`}<div class="form-actions">${btn('← Back to details','back-details','button secondary')}${btn('Continue to payment '+icon('arrow'),'to-cash','button')}</div></div>`;}
function cashView(){const t=paymentTotals(ui.draft,ui.cash);return `<form data-form="cash" class="panel form-panel"><h2>Per-person payment</h2><p class="subtle">Cash only. Each attendee has their own payment status.</p><div class="payment-rows">${ui.draft.map(p=>`<div class="payment-row"><div><b>${esc(p.name)}</b><small>${p.guardian?'Guardian · ':''}${money(p.fee)}${p.precovered?' · Support already noted':''}</small></div><label class="field"><span class="sr-only">Payment for ${esc(p.name)}</span><select data-payment="${p.id}">${options(['Paid','Pending','Covered'],p.payment)}</select></label>${p.payment==='Covered'?`<label class="checkbox-line coverage-check"><input type="checkbox" data-coverage="${p.id}" ${p.coverageApproved?'checked':''}><span>I approve coverage under ${esc(session.name)}’s login.<small>Private to desk staff. It will not appear on their ticket.</small></span></label>`:''}</div>`).join('')}</div><div class="cash-entry"><div><span class="eyebrow">TICKET CASH DUE</span><strong id="cash-due">${money(t.due)}</strong></div>${field('Cash received *','cash',ui.cash,'required min="0" step="0.01" inputmode="decimal"','number')}</div><div id="cash-breakdown">${cashBreakdown()}</div><div class="form-actions">${btn('← Back to waivers','back-waiver','button secondary')}<button class="button" type="submit">Save ${ui.draft.length===1?'registration':'registrations'} ${icon('check')}</button></div><p class="subtle small-copy">This records fake cash only. No payment service is connected.</p></form>`;}
function cashBreakdown(){const t=paymentTotals(ui.draft,ui.cash);return `<div class="money-breakdown"><div><span>Ticket payments</span><b>${money(t.due)}</b></div><div class="donation-line"><span>${icon('heart')} Donation to affordability pool</span><b>${money(t.donation)}</b></div>${t.covered?`<div><span>Covered by pool</span><b>${money(t.covered)}</b></div>`:''}${t.pending?`<div><span>Still pending</span><b>${money(t.pending)}</b></div>`:''}</div>${t.donation?`<div class="notice success">${money(t.donation)} of the cash received will be recorded as a donation. Confirm this with the payer before saving.</div>`:''}`;}
function confirmationView(){const rows=ui.confirmation.map(id=>state.registrations.find(r=>r.id===id)).filter(Boolean);return `${titleBlock('REGISTRATIONS SAVED','You’re all set at the desk.',`${rows.filter(isComplete).length} complete · ${rows.filter(r=>!isComplete(r)).length} awaiting a follow-up`,btn('Start next registration '+icon('plus'),'next-registration','button'))}<div class="confirmation-grid">${rows.map(r=>`<article class="panel confirmation-card"><div class="ticket-card-top"><span class="eyebrow">${r.id}</span>${statusBadge(r)}</div><h2>${esc(r.name)}</h2><p>${esc(zoneFor(r.age))} · ${esc(r.size)}</p>${isComplete(r)?`<div class="qr small-qr">${qrHTML(linkFor('ticket',r))}</div><p class="subtle">Personal ticket ready</p>`:`<div class="pending-art">${icon('clock')}<b>${statusFor(r)}</b><p>${r.waiver==='Waiting on parent'?'A ticket becomes ready after the parent signs and payment is settled.':'A ticket becomes ready after payment is settled.'}</p></div>`}<div class="button-stack">${btn('Open personal ticket','open-ticket','button secondary',`data-id="${r.id}"`)}${r.age<18&&r.waiver!=='Signed'?btn('Preview parent text & link','parent-link','text-button',`data-id="${r.id}"`):btn('Preview ticket message','ticket-message','text-button',`data-id="${r.id}"`)}</div></article>`).join('')}</div><div class="notice">${icon('check')}<p>Saved in this browser’s demo data. Each person has a separate registration. No real text was sent.</p></div>`;}
function registrationsView(){const all=scopedRows(state,ctx()),rows=all.filter(r=>(ui.filter==='All statuses'||statusFor(r)===ui.filter)&&(r.name+' '+r.phone+' '+r.id).toLowerCase().includes(ui.listSearch.toLowerCase()));return `${titleBlock('REGISTRATIONS',session.role==='super'?'Every desk, in one place.':'Your Jamatkhana’s registrations.',`${all.length} saved registrations · ${all.filter(isComplete).length} complete`,btn('New registration '+icon('plus'),'new-registration','button'))}<div class="panel records-panel"><div class="table-toolbar"><label class="field search-control"><span class="sr-only">Search registrations</span><div class="input-icon">${icon('search')}<input id="list-search" placeholder="Search name, phone or ticket ID" value="${esc(ui.listSearch)}"></div></label>${select('Status','status-filter',['All statuses','Complete','Waiting on parent','Payment pending'],ui.filter)}<span class="subtle" id="result-count">${rows.length} shown</span></div><div id="records-list">${recordsTable(rows,all.length)}</div></div>`;}
function recordsTable(rows,total){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Attendee</th><th>Jamatkhana / zone</th><th>T-shirt</th><th>Waiver</th><th>Payment</th><th>Status</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${rows.map(r=>`<tr class="${r.guardian?'guardian-row':''}"><td data-label="Attendee"><b>${esc(r.name)}</b><small>${r.id}${r.guardian?' · Guardian':''}</small></td><td data-label="Jamatkhana / zone">${esc(r.jk)}<small>${zoneFor(r.age)}</small></td><td data-label="T-shirt">${esc(r.size)}</td><td data-label="Waiver">${badge(r.waiver,r.waiver==='Waiting on parent'?'warning':'neutral')}</td><td data-label="Payment">${badge(r.payment,r.payment==='Pending'?'warning':r.payment==='Covered'?'blue':'success')}<small>${money(r.fee)}</small></td><td data-label="Status">${statusBadge(r)}</td><td>${btn('View '+icon('chevron'),'record','text-button',`data-id="${r.id}" aria-label="View ${esc(r.name)}"`)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${icon('users')}<h2>${total?'No registrations match these filters':'No registrations yet'}</h2><p>${total?'Try another name or clear the filters.':'Start with a phone search at your desk.'}</p>${btn(total?'Clear filters':'Register someone',total?'clear-filters':'new-registration','button secondary')}</div>`;}
function metric(label,value,note='',cls=''){return `<div class="metric ${cls}"><span>${label}</span><strong>${value}</strong><small>${note}</small></div>`;}
function breakdown(title,items,empty='No registrations yet'){const max=Math.max(1,...Object.values(items));return `<section class="panel breakdown"><h2>${title}</h2>${Object.keys(items).length?Object.entries(items).map(([label,count])=>`<div class="bar-row"><div><span>${esc(label)}</span><b>${count}</b></div><div class="bar-track"><i style="width:${count/max*100}%"></i></div></div>`).join(''):`<p>${empty}</p>`}</section>`;}
function reportsView(){if(session.role==='desk')return deniedView('Reports are available to JK admins and super admins.');const scope=session.role==='super'?ui.reportJk:session.jk,a=aggregate(state,scope),regional=aggregate(state),logs=state.logs.filter(l=>scope==='All JKs'||l.jk===scope);const cashBy={};a.tx.forEach(t=>{const k=t.jk+' · '+t.actor+' · '+dateLabel(t.date);cashBy[k]=(cashBy[k]||0)+t.amount;});return `${titleBlock('REPORTS','The day, accounted for.','Registrations, shirts and cash - from the same records.',btn(icon('download')+'Export CSV','export-csv','button secondary'))}${session.role==='super'?`<div class="report-filter">${select('Reporting scope','report-scope',['All JKs',...JKS],scope)}</div>`:`<p class="scope-note">${icon('pin')} ${esc(scope)} only</p>`}<div class="metrics">${metric('Registrations',a.count,a.complete+' complete')}${metric('Cash collected',money(a.cash),'Tickets + donations')}${metric('Payment pending',money(a.pending),'Not included in cash')}${metric('Waiting on parent',a.waiting,'Waiver follow-up')}</div><div class="report-grid">${breakdown('Age zones',Object.fromEntries(['Youth 8–12','Youth 13–18','Adults 19–64','Senior 65+'].map(z=>[z,a.zones[z]||0])))}${breakdown('T-shirt sizes',a.shirts)}<section class="panel pool-panel"><div class="eyebrow">REGIONAL AFFORDABILITY POOL</div><h2>${money(regional.pool)}</h2><p>Across all 11 Jamatkhanas and the event desk.</p><div class="stat-line"><span>Donations received</span><b>${money(regional.donations)}</b></div><div class="stat-line"><span>Covered registration fees</span><b>−${money(regional.covered)}</b></div>${regional.pool<0?'<div class="notice warning">The pool has a shortfall. Desk coverage can still be approved.</div>':''}<small>Private reporting. Coverage is never shown on attendee tickets.</small></section><section class="panel breakdown"><h2>Registration details</h2><div class="stat-line"><span>Accompanying guardians</span><b>${a.guardians}</b></div><div class="stat-line"><span>Early · $15</span><b>${a.early}</b></div><div class="stat-line"><span>Standard · $20</span><b>${a.regular}</b></div><div class="stat-line"><span>Ticket cash</span><b>${money(a.ticketCash)}</b></div><div class="stat-line"><span>Donations in this scope</span><b>${money(a.donations)}</b></div><div class="stat-line"><span>Coverage in this scope</span><b>${money(a.covered)}</b></div></section></div><section class="panel report-table"><h2>By Jamatkhana</h2><div class="table-wrap"><table><thead><tr><th>Jamatkhana</th><th>Registrations</th><th>Cash</th><th>Donations</th><th>Covered</th></tr></thead><tbody>${(scope==='All JKs'?JKS:[scope]).map(j=>{const x=aggregate(state,j);return `<tr><td data-label="Jamatkhana">${j}</td><td data-label="Registrations">${x.count}</td><td data-label="Cash">${money(x.cash)}</td><td data-label="Donations">${money(x.donations)}</td><td data-label="Covered">${money(x.covered)}</td></tr>`;}).join('')}</tbody></table></div></section><div class="report-grid">${breakdown('Teams',a.teams)}<section class="panel breakdown"><h2>Cash by desk, volunteer & day</h2>${Object.entries(cashBy).map(([k,v])=>`<div class="stat-line"><span>${esc(k)}</span><b>${money(v)}</b></div>`).join('')||'<p>No cash receipts in this scope.</p>'}</section></div><section class="panel audit-panel"><div class="section-title"><h2>Desk activity</h2><span class="subtle">${logs.length} logged actions</span></div>${logs.length?logs.slice().reverse().slice(0,30).map(l=>`<div class="audit-row"><span class="audit-mark">${icon(l.type.includes('Coverage')?'heart':'check')}</span><div><b>${esc(l.type)}</b><p>${esc(l.name||l.detail)}</p><small>${esc(l.actor)} · ${esc(l.jk)} · ${dateLabel(l.date)} ${esc(l.time||'')}</small>${l.name?`<small>${esc(l.detail||'')}</small>`:''}</div></div>`).join(''):'<p>No desk activity recorded.</p>'}</section>`;}
function closeData(){const jk=session.role==='super'?ui.closeJk:session.jk,tx=state.transactions.filter(t=>t.jk===jk&&t.date===ui.closeDate),closes=state.closes.filter(c=>c.jk===jk&&c.date===ui.closeDate),closed=new Set(closes.flatMap(c=>c.receiptIds)),open=tx.filter(t=>!closed.has(t.id));return{jk,tx,closes,open,expected:open.reduce((s,t)=>s+t.amount,0)};}
function closeView(){if(session.role==='desk')return deniedView('Cash close is available to JK admins and super admins.');const d=closeData();return `${titleBlock('DAILY CASH CLOSE','Count. Confirm. Hand over.','Reconcile cash collected at your desk with the day’s recorded receipts.')}<div class="report-filter">${session.role==='super'?select('Desk','close-jk',JKS,d.jk):`<span class="scope-note">${esc(d.jk)}</span>`}${field('Cash date','close-date',ui.closeDate,'max="2026-11-22"','date')}</div><div class="wizard-grid"><form class="panel form-panel" data-form="close"><div class="eyebrow">UNCLOSED RECEIPTS</div><div class="close-amount">${money(d.expected)}</div><p class="subtle">${d.open.length} receipts · ticket payments plus donations</p>${d.closes.length?`<div class="notice">${d.closes.length} earlier close(s) recorded. This close includes only receipts received since those handovers.</div>`:''}<div class="form-divider"></div>${field('Cash counted *','counted','','required min="0" step="0.01" inputmode="decimal"','number')}<div id="variance-preview" class="variance">Enter the cash counted to compare.</div>${field('Handed to *','handedTo','','required placeholder="Full name of receiving volunteer"')}<label class="field"><span>Explanation if the count differs</span><textarea name="note" rows="3" placeholder="Explain any overage or shortage"></textarea></label><div class="form-actions"><span class="subtle">Closed by ${esc(session.name)}</span><button class="button" type="submit">Record cash close ${icon('check')}</button></div>${errorBox()}</form><aside class="panel breakdown"><h2>Day’s cash summary</h2><div class="stat-line"><span>All cash received</span><b>${money(d.tx.reduce((s,t)=>s+t.amount,0))}</b></div><div class="stat-line"><span>Ticket cash</span><b>${money(d.tx.reduce((s,t)=>s+t.ticketAmount,0))}</b></div><div class="stat-line"><span>Donations</span><b>${money(d.tx.reduce((s,t)=>s+t.donation,0))}</b></div><p class="subtle">Pending and Covered are excluded from expected physical cash.</p>${d.closes.map(c=>`<div class="closed-record">${badge('Close recorded','success')}<h3>${money(c.counted)} handed over</h3><p>To ${esc(c.handedTo)}<br>By ${esc(c.actor)}</p><small>Expected ${money(c.expected)} · Difference ${money(c.variance)}</small>${c.note?`<p>${esc(c.note)}</p>`:''}</div>`).join('')}</aside></div>`;}
function deniedView(message){return `${titleBlock('ACCESS','This view needs an admin account.')}<div class="panel empty">${icon('shield')}<p>${message}</p><a href="#desk" class="button">Return to the desk</a></div>`;}
function eventView(){return `${publicHeader()}<main id="main" class="event-page"><section class="event-hero"><div class="event-hero-copy"><div class="eyebrow">ISMAILI VOLUNTEERS · CENTRAL USA</div><h1>Celebration<br>of Service<span>2026</span></h1><p class="event-intro">A day to come together.<br>For the volunteers who give so much.</p><div class="hero-date"><span>22<small>NOVEMBER</small></span><div><b>Sunday, 2026</b><p>9:00 AM – 3:00 PM</p></div></div></div><div class="emblem-wrap">${logo()}</div></section><section class="event-facts"><div>${icon('pin')}<span><b>Plano Sports Authority 2</b><small>601 Seabrook Dr, Plano, TX 75023</small></span></div><div>${icon('shirt')}<span><b>$15 through November 6</b><small>$20 from November 7 · T-shirt included</small></span></div></section><section class="event-section registration-explainer"><div><div class="eyebrow">HOW TO JOIN</div><h2>A friendly face.<br>A registration desk.</h2><p>Register in person at your Jamatkhana through November 22, or at the venue on event day.</p><p class="subtle">Registration is handled by desk volunteers. There is no online self-registration.</p></div><ol class="event-steps"><li><span>01</span><div><h3>Visit your registration desk</h3><p>Bring the phone number on your volunteer record. We’ll find your family together.</p></div></li><li><span>02</span><div><h3>Confirm details & parent permission</h3><p>Choose a T-shirt size. A parent signs for anyone under 18.</p></div></li><li><span>03</span><div><h3>Pay cash & receive your ticket</h3><p>The fee is per person, including guardians. Each attendee receives a personal ticket.</p></div></li></ol></section><section class="event-section eligibility-section"><div><div class="eyebrow">WHO CAN COME</div><h2>A celebration<br>across generations.</h2><p>Active Central Region Ismaili Volunteers, ages 8–90, who have completed Code of Conduct training.</p><p>Ages 8–15 must attend with one adult guardian. A guardian can accompany multiple children and does not need to be an active volunteer or have COC. They register, pay and participate too.</p><p>For ages 16–17, a parent who is away can sign from a personal link.</p></div><div class="zones">${[['08–12','Youth','Space for our youngest volunteers'],['13–18','Youth','Come together with your peers'],['19–64','Adults','A day of community and connection'],['65+','Seniors','Everyone has a place here']].map(([a,t,d])=>`<div class="zone-row"><strong>${a}</strong><span><b>${t}</b><small>${d}</small></span></div>`).join('')}</div></section><section class="event-section venue-section"><div><div class="eyebrow">SEE YOU IN PLANO</div><h2>One place.<br>Our whole community.</h2><h3>Plano Sports Authority 2</h3><p>601 Seabrook Dr<br>Plano, TX 75023</p><a class="button" href="${directions}" target="_blank" rel="noopener">Get directions ${icon('external')}</a></div><div class="venue-map"><iframe title="Map of Plano Sports Authority 2, 601 Seabrook Drive" src="https://maps.google.com/maps?q=Plano%20Sports%20Authority%202%20601%20Seabrook%20Dr%20Plano%20TX&t=&z=14&ie=UTF8&iwloc=&output=embed" loading="lazy" referrerpolicy="no-referrer-when-downgrade"></iframe><a href="${directions}" target="_blank" rel="noopener">Open venue map ${icon('external')}</a></div></section><section class="jk-strip"><span class="eyebrow">YOUR LOCAL REGISTRATION DESKS</span><p>${JKS.filter(j=>j!=='Event-day desk').join(' · ')}</p></section><footer class="event-footer"><div><span class="wordmark">IVC 2026</span><p>Celebration of Service · Central USA</p></div><div><b>Need help?</b><p>Contact email & phone: coming soon<br>COC training link: placeholder</p></div></footer></main>`;}
function readPublic(routed){const data=unpack(routed);if(!data||typeof data.id!=='string'||typeof data.name!=='string'||typeof data.age!=='number')return null;const local=state.registrations.find(r=>r.id===data.id);return {public:local?publicPerson(local):data,local};}
function invalidLink(){return `${publicHeader()}<main id="main" class="mobile-page"><div class="panel empty">${icon('shield')}<h1>This personal link isn’t valid.</h1><p>Ask the registration desk for your personal link.</p><a class="button" href="#event">View event details</a></div></main>`;}
function ticketView(encoded){const entry=readPublic(encoded);if(!entry)return invalidLink();const p=entry.public;return `${publicHeader()}<main id="main" class="mobile-page ticket-page"><div class="mobile-intro"><span class="eyebrow">YOUR PERSONAL TICKET</span><h1>See you at IVC.</h1><p>Sunday, November 22 · 9 AM – 3 PM</p></div><article class="admission-ticket"><div class="ticket-brand"><span>IVC <b>2026</b></span><small>CENTRAL USA</small></div><div class="ticket-person"><span class="eyebrow">${p.guardian?'ACCOMPANYING GUARDIAN':'ATTENDEE'}</span><h2>${esc(p.name)}</h2><p>${esc(p.jk)}</p><div class="ticket-tags">${badge(zoneFor(p.age))}${badge(p.size||'Size pending')}</div></div><div class="ticket-perforation"></div><div class="ticket-qr">${p.complete?`${badge('Registration complete','success')}<div class="qr">${qrHTML(location.href.split('#')[0]+'#ticket/'+encoded)}</div><p>Keep this ticket handy for event day.</p>`:`${badge(p.status||'Registration in progress','warning')}<div class="pending-art">${icon('clock')}<h3>Your ticket is being prepared.</h3><p>${p.status==='Waiting on parent'?'Your parent still needs to sign the waiver.':'Please check with your registration desk to finish the remaining step.'}</p></div>`}<small>${esc(p.id)}</small></div><div class="ticket-location">${icon('pin')}<div><b>Plano Sports Authority 2</b><p>601 Seabrook Dr, Plano, TX 75023</p></div></div></article><a class="button secondary full" href="${directions}" target="_blank" rel="noopener">Get directions ${icon('external')}</a><a class="text-link centered" href="#event">View event details</a><p class="demo-footnote">Sample ticket · fake attendee data</p></main>`;}
function parentView(encoded){const entry=readPublic(encoded);if(!entry||entry.public.age>=18)return invalidLink();const p=entry.public;let remoteSigned=false;try{remoteSigned=!!localStorage.getItem('ivc-waiver-'+p.id);}catch{}const signed=entry.local?.waiver==='Signed'||remoteSigned;return `${publicHeader()}<main id="main" class="mobile-page waiver-page"><span class="eyebrow">PARENT / LEGAL GUARDIAN</span><h1>${signed?'Thank you for signing.':'A little permission.\nA big day ahead.'}</h1><p class="mobile-description">${signed?'The sample parent waiver has been recorded on this device.':'Please review and sign the sample waiver for your child.'}</p><div class="panel child-context"><span class="person-avatar">${esc(p.name[0])}</span><div><h2>${esc(p.name)}</h2><p>Age ${p.age} · IVC 2026 · November 22</p></div></div>${signed?`<div class="panel signed-confirmation">${icon('check')}<h2>Parent waiver signed</h2><p>Thank you. The registration desk can now finish any remaining registration steps.</p><div class="notice">Demo: a desk tab in this same browser updates automatically. Separate devices do not sync because this prototype has no backend.</div>${entry.local?btn('View personal ticket','open-ticket','button full',`data-id="${p.id}"`):'<a class="button full" href="#event">View event details</a>'}</div>`:`<form data-form="parent" data-payload="${esc(encoded)}" class="panel form-panel">${waiverText}${signatureFields()}${errorBox()}<button class="button full" type="submit">Sign parent waiver ${icon('check')}</button><p class="demo-footnote">This is a prototype waiver. Use a fictional name; no real consent is collected.</p></form>`}</main>`;}
function render(){const active=document.activeElement,wasInApp=active&&$('#app').contains(active),focusSelector=active?.dataset?.person?'[data-person="'+active.dataset.person+'"]':active?.dataset?.payment?'[data-payment="'+active.dataset.payment+'"]':null;const route=location.hash.slice(1)||'desk',key=route.split('/')[0];document.title=key==='event'?'IVC 2026 · Celebration of Service':key==='ticket'?'Your IVC 2026 ticket':'IVC 2026 · Registration Desk';if(key==='event')$('#app').innerHTML=eventView();else if(key==='ticket')$('#app').innerHTML=ticketView(route.slice(7));else if(key==='waiver')$('#app').innerHTML=parentView(route.slice(7));else if(!session)$('#app').innerHTML=loginView();else $('#app').innerHTML=shell(key==='registrations'?registrationsView():key==='reports'?reportsView():key==='close'?closeView():deskView(),key);setupCanvas();if(wasInApp){const target=focusSelector?document.querySelector(focusSelector):null;if(target)target.focus({preventScroll:true});else{const heading=$('#main h1');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}}}}
function openDialog(title,body){const d=$('#dialog');d.innerHTML=`<div class="dialog-heading"><h2>${title}</h2>${btn(icon('close'),'close-dialog','icon-button','aria-label="Close dialog"')}</div>${body}`;d.showModal();setupCanvas();}
function dialogError(message){let e=$('#dialog .dialog-error');if(!e){e=document.createElement('div');e.className='notice error dialog-error';e.setAttribute('role','alert');$('#dialog').append(e);}e.textContent=message;}
function addLog(type,name,detail=''){const c=ctx();state.logs.push({id:uid('audit'),type,name,detail,actor:c.actor,jk:c.jk,date:c.date,time:c.time});}
function search(){const value=digits(ui.search);ui.error='';if(value.length!==10){ui.error='Enter a 10-digit phone number, including area code.';render();return;}ui.search=value;ui.loading=true;ui.results=null;render();setTimeout(()=>{ui.results=getPeople().filter(p=>digits(p.phone)===value);ui.selected=[];ui.loading=false;render();},160);}
function begin(){const selected=ui.results.filter(p=>ui.selected.includes(p.id));if(selected.some(p=>!p.guardian&&(!p.coc||!p.active))){ui.error='Resolve COC and active status for everyone selected before continuing.';render();return;}if(demoDate>EVENT_DATE){ui.error='Registration closed after November 22.';render();return;}const prior=new Map(ui.draft.map(p=>[p.id,p]));ui.draft=selected.sort((a,b)=>b.age-a.age).map(p=>prior.get(p.id)||({...p,_original:{name:p.name,age:p.age,phone:p.phone,jk:p.jk},fee:feeFor(demoDate),payment:p.precovered?'Covered':'Paid',waiver:p.age>=18?'Not required':'',size:'',guardianId:'',emergencyName:'Demo Contact',emergencyPhone:'2145550198'}));ui.current=0;ui.step=1;ui.error='';render();}
function recordDialog(id){const r=state.registrations.find(r=>r.id===id);if(!r||session.role!=='super'&&r.deskJk!==session.jk){toast('This record is outside your desk.');return;}const guardian=state.registrations.find(g=>g.id===r.guardianId);const children=state.registrations.filter(p=>p.guardianId===r.id);openDialog(esc(r.name),`<div class="record-status">${statusBadge(r)}${r.guardian?badge('Guardian','blue'):''}</div><dl class="record-details"><div><dt>Ticket ID</dt><dd>${r.id}</dd></div><div><dt>Jamatkhana</dt><dd>${esc(r.jk)}</dd></div><div><dt>Age / zone</dt><dd>${r.age} · ${zoneFor(r.age)}</dd></div><div><dt>T-shirt</dt><dd>${esc(r.size)}</dd></div><div><dt>Waiver</dt><dd>${esc(r.waiver)}</dd></div><div><dt>Payment</dt><dd>${esc(r.payment)} · ${money(r.fee)}</dd></div>${guardian?`<div><dt>Guardian</dt><dd>${esc(guardian.name)}</dd></div>`:''}${children.length?`<div><dt>Children</dt><dd>${children.map(p=>esc(p.name)).join(', ')}</dd></div>`:''}</dl><div class="button-stack">${r.payment==='Pending'?btn('Collect pending cash','collect','button',`data-id="${id}"`):''}${r.age<18&&r.waiver!=='Signed'?btn('Preview parent text & link','parent-link','button secondary',`data-id="${id}"`):''}${btn('Open personal ticket','open-ticket','button secondary',`data-id="${id}"`)}${isComplete(r)?btn('Preview ticket message','ticket-message','text-button',`data-id="${id}"`):''}</div><p class="subtle small-copy">Recorded at ${esc(r.deskJk)} · ${esc(r.actor)} · ${dateLabel(r.date)}</p>`);}
function setupCanvas(){document.querySelectorAll('.signature-canvas').forEach(canvas=>{const context=canvas.getContext('2d');context.lineWidth=2.5;context.lineCap='round';context.strokeStyle='#302c28';let drawing=false;const pt=e=>{const r=canvas.getBoundingClientRect();return[(e.clientX-r.left)*canvas.width/r.width,(e.clientY-r.top)*canvas.height/r.height];};canvas.onpointerdown=e=>{drawing=true;canvas.setPointerCapture(e.pointerId);context.beginPath();context.moveTo(...pt(e));};canvas.onpointermove=e=>{if(!drawing)return;context.lineTo(...pt(e));context.stroke();canvas.dataset.signed='true';};canvas.onpointerup=()=>drawing=false;canvas.onpointercancel=()=>drawing=false;});}
function signatureValue(form){const drawn=form.dataset.signatureMode==='draw';return drawn?(form.querySelector('canvas')?.dataset.signed==='true'?'Drawn signature':''):form.elements.signature?.value.trim();}
function saveSignature(form){const name=form.elements.parentName.value.trim(),signature=signatureValue(form);if(!name||!signature||!form.elements.consent.checked)throw Error('Enter the parent’s name, add a signature and check the consent box.');return{name,signature,method:form.dataset.signatureMode==='draw'?'Drawn':'Typed'};}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('Personal demo link copied.');}catch{openDialog('Copy personal link',`<label class="field"><span>Select and copy this link</span><textarea rows="5">${esc(text)}</textarea></label>`);}}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;ui.error='';
try{switch(action){
case'close-dialog':$('#dialog').close();break;
case'signout':if(ui.step&&!confirm('Discard the unsaved registration and sign out?'))return;session=null;sessionStorage.removeItem('ivc-session');ui.step=0;ui.draft=[];ui.confirmation=[];render();break;
case'scenario':ui.search=el.dataset.phone;search();break;
case'clear-search':ui.search='';ui.results=null;ui.selected=[];render();break;
case'begin':begin();break;
case'add-person':case'add-guardian':openDialog(action==='add-guardian'?'Add an accompanying guardian':'Add a person for verification',`<form data-form="add-person"><p class="subtle">${action==='add-guardian'?'An adult guardian registers and pays separately. Link them to their child in the next step.':'No matching volunteer record was found. Eligibility must be verified before registration.'}</p><div class="field-grid">${field('Full name *','name','','required')}${field('Age at the event *','age',action==='add-guardian'?40:25,`required min="${action==='add-guardian'?18:8}" max="90"`,'number')}${field('Phone *','phone',phone(ui.search),'required inputmode="tel"','tel')}${select('Home Jamatkhana','jk',JKS.filter(j=>j!=='Event-day desk'),session.jk==='Event-day desk'?'Dallas HQ':session.jk)}</div><input type="hidden" name="guardian" value="${action==='add-guardian'?'yes':'no'}"><button class="button full" type="submit">${action==='add-guardian'?'Add guardian':'Add for eligibility verification'}</button></form>`);break;
case'eligibility':{const p=getPeople().find(p=>p.id===id),kind=el.dataset.kind;openDialog(kind==='coc'?'Record COC completion':'Confirm active volunteer',`<form data-form="eligibility" data-id="${id}" data-kind="${kind}"><p><b>${esc(p.name)}</b> · ${esc(session.jk)} desk</p>${kind==='coc'?`<div class="notice">COC training link is a placeholder in this demo.</div><label class="checkbox-line"><input type="checkbox" name="verified" required><span>I verified that this person completed their COC training at the desk.</span></label>`:`<p class="subtle">Record the facilitator who confirmed this volunteer is active.</p>${field('Facilitator name *','facilitator','','required')}${field('Facilitator phone *','facilitatorPhone','','required inputmode="tel"','tel')}`}<p class="subtle">This event-only record will include ${esc(session.name)}, the desk, date and time. The master COC record stays unchanged.</p><button class="button full" type="submit">${kind==='coc'?'Record completion':'Record confirmation'}</button></form>`);break;}
case'back-search':ui.step=0;render();break;
case'previous-person':ui.current=Math.max(0,ui.current-1);render();break;
case'remove-person':{const p=ui.draft[ui.current];if(ui.draft.some(x=>x.guardianId===p.id)){ui.error='This person is an assigned guardian. Reassign their children before removing them.';render();break;}ui.draft.splice(ui.current,1);ui.current=Math.min(ui.current,ui.draft.length-1);render();break;}
case'back-details':ui.step=1;ui.current=ui.draft.length-1;render();break;
case'discard':if(confirm('Discard this unsaved registration? Saved registrations will stay.')){ui.step=0;ui.draft=[];render();}break;
case'sign-child':{const p=ui.draft.find(p=>p.id===id);openDialog(`Parent waiver · ${esc(p.name)}`,p.waiver==='Signed'?`<div class="notice success">Signed by ${esc(p.parentName)} using a ${esc(p.signatureMethod?.toLowerCase()||'typed')} signature.</div>${btn('Replace sample signature','replace-signature','button secondary',`data-id="${id}"`)}`:`<form data-form="child-sign" data-id="${id}">${waiverText}${signatureFields(p.parentName||'')}<button class="button full" type="submit">Save parent signature ${icon('check')}</button></form>`);break;}
case'replace-signature':{const p=ui.draft.find(p=>p.id===id);$('#dialog').close();openDialog(`Parent waiver · ${esc(p.name)}`,`<form data-form="child-sign" data-id="${id}">${waiverText}${signatureFields(p.parentName||'')}<button class="button full" type="submit">Save parent signature</button></form>`);break;}
case'parent-away':{const p=ui.draft.find(p=>p.id===id);openDialog('Prepare a parent link',`<form data-form="parent-away" data-id="${id}"><p>A parent can sign for <b>${esc(p.name)}</b> from their phone. Until then, this registration will show <b>Waiting on parent</b>.</p>${field('Parent / legal guardian name *','parentName',p.parentName||'','required')}${field('Parent phone *','parentPhone',p.parentPhone?phone(p.parentPhone):'','required inputmode="tel"','tel')}<div class="notice">Demo only: after saving the registration, you can preview the text and open the parent link. No SMS is sent.</div><button type="submit" class="button full">Save as waiting on parent</button></form>`);break;}
case'signature-type':case'signature-draw':{const root=el.closest('.signature-fields'),form=el.closest('form'),draw=action==='signature-draw';form.dataset.signatureMode=draw?'draw':'type';root.querySelector('.typed-signature').hidden=draw;root.querySelector('.drawn-signature').hidden=!draw;root.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===el));break;}
case'clear-signature':{const c=el.closest('.drawn-signature').querySelector('canvas');c.getContext('2d').clearRect(0,0,c.width,c.height);delete c.dataset.signed;break;}
case'to-cash':{const invalid=ui.draft.find(p=>p.age<18&&p.waiver!=='Signed'&&!(p.age>=16&&p.waiver==='Waiting on parent'));if(invalid){ui.error='Complete the parent waiver step for '+invalid.name+'.';render();break;}ui.step=3;if(ui.cash==='')ui.cash=String(paymentTotals(ui.draft).due);render();break;}
case'back-waiver':ui.step=2;render();break;
case'next-registration':case'new-registration':if(ui.step&&!confirm('Discard the unsaved draft and start a new registration?'))return;ui.step=0;ui.draft=[];ui.cash='';ui.confirmation=[];ui.results=null;ui.selected=[];ui.search='';nav('desk');break;
case'record':recordDialog(id);break;
case'collect':{const r=state.registrations.find(r=>r.id===id);$('#dialog').close();openDialog('Collect pending cash',`<form data-form="collect" data-id="${id}"><h3>${esc(r.name)}</h3><p>Original registration fee: <b>${money(r.fee)}</b><br><small>The fee stays the same, even after November 6.</small></p>${field('Cash received *','cash',r.fee,'required min="'+r.fee+'" step="0.01"','number')}<p class="notice">Cash above ${money(r.fee)} becomes a donation to the affordability pool.</p><button class="button full" type="submit">Record cash payment</button></form>`);break;}
case'open-ticket':{const r=state.registrations.find(r=>r.id===id);$('#dialog').close();location.hash=linkFor('ticket',r).split('#')[1];break;}
case'parent-link':case'ticket-message':{const r=state.registrations.find(r=>r.id===id);if(!r)return;const parent=action==='parent-link',url=linkFor(parent?'waiver':'ticket',r);$('#dialog').close();openDialog(parent?'Parent text preview':'Ticket text preview',`<span class="eyebrow">SIMULATED MESSAGE · NOT SENT</span><div class="sms-preview">${parent?`IVC 2026: Please review and sign the parent waiver for ${esc(r.name)}. Their registration is waiting on your signature.`:`IVC 2026: ${esc(r.name)}, your registration is complete. Here is your personal ticket for November 22 at Plano Sports Authority 2.`}<br><span class="sms-link">Personal ${parent?'waiver':'ticket'} link</span></div><p class="subtle">${parent?'To: '+phone(r.parentPhone||r.phone):'To: '+phone(r.phone)}</p><div class="button-stack"><a class="button full" href="${esc(url)}" target="_blank" rel="noopener">Open ${parent?'parent page':'ticket'} ${icon('external')}</a>${btn('Copy personal link','copy-link','button secondary',`data-url="${esc(url)}"`)}</div><div class="notice">All data is fictional. Parent signing updates desk tabs in this same browser. Separate devices do not sync.</div>`);break;}
case'copy-link':await copyText(el.dataset.url);break;
case'clear-filters':ui.filter='All statuses';ui.listSearch='';render();break;
case'demo-controls':openDialog('Demo controls',`<form data-form="demo"><p class="subtle">Explore roles, desks and both registration prices. Changes stay in this browser.</p>${select('Demo date','demoDate',['2026-11-06','2026-11-07','2026-11-22','2026-11-23'],demoDate)}<p class="field-help">Nov 6: $15 · Nov 7: $20 · Nov 22: event day · Nov 23: closed</p><label class="field"><span>Account role</span><select name="account">${ACCOUNTS.slice(0,3).map((a,i)=>`<option value="${i}" ${session.role===a.role?'selected':''}>${a.name} - ${a.label}</option>`).join('')}</select></label>${select('Assigned / operating desk','jk',JKS,session.jk)}<button type="submit" class="button full">Apply demo settings</button></form><div class="form-divider"></div><div class="demo-shortcuts"><a href="#event" data-action="close-dialog">Public event page ${icon('arrow')}</a>${btn('Open sample parent link','sample-parent','text-button')}${btn('Open sample ticket','sample-ticket','text-button')}</div><p class="small-copy subtle">Google, SMS and Sheets are simulated. This is a browser demo, not a secure registration service. Please use fake information only.</p>${btn('Reset demo data','reset','text-button danger')}`);break;
case'reset':if(confirm('Reset all fake registrations, signatures, receipts and cash closes to the starting demo?')){state=createInitialState();persist();for(let i=localStorage.length-1;i>=0;i--){const k=localStorage.key(i);if(k.startsWith('ivc-waiver-'))localStorage.removeItem(k);}ui.draft=[];ui.step=0;ui.cash='';ui.confirmation=[];ui.results=null;$('#dialog').close();nav('desk');toast('Demo reset to the starting sample data.');}break;
case'sample-parent':{const r=state.registrations.find(r=>r.age<18&&r.waiver!=='Signed')||state.registrations.find(r=>r.age<18);$('#dialog').close();location.hash=linkFor('waiver',r).split('#')[1];break;}
case'sample-ticket':{const r=state.registrations.find(isComplete);$('#dialog').close();location.hash=linkFor('ticket',r).split('#')[1];break;}
case'export-csv':exportCsv();break;
}}catch(err){toast(err.message);}});
document.addEventListener('input',e=>{const t=e.target;if(t.matches('[data-draft]')){ui.draft[ui.current][t.name]=t.name==='age'?+t.value:t.name==='size'&&t.value==='Choose a size'?'':t.value;}if(t.name==='cash'&&t.closest('[data-form="cash"]')){ui.cash=t.value;$('#cash-breakdown').innerHTML=cashBreakdown();}if(t.id==='list-search'){ui.listSearch=t.value;const all=scopedRows(state,ctx()),rows=all.filter(r=>(ui.filter==='All statuses'||statusFor(r)===ui.filter)&&(r.name+' '+r.phone+' '+r.id).toLowerCase().includes(ui.listSearch.toLowerCase()));$('#records-list').innerHTML=recordsTable(rows,all.length);$('#result-count').textContent=rows.length+' shown';}if(t.name==='counted'){const difference=Number(t.value)-closeData().expected;$('#variance-preview').textContent=t.value===''?'Enter the cash counted to compare.':difference===0?'Cash matches the expected amount.':`${money(Math.abs(difference))} ${difference<0?'short':'over'} - please explain the difference below.`;$('#variance-preview').className='variance '+(difference===0?'matched':'mismatch');}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.person){if(t.checked)ui.selected.push(t.dataset.person);else ui.selected=ui.selected.filter(id=>id!==t.dataset.person);render();}if(t.dataset.payment){ui.draft.find(p=>p.id===t.dataset.payment).payment=t.value;ui.cash=String(paymentTotals(ui.draft).due);render();}if(t.dataset.coverage)ui.draft.find(p=>p.id===t.dataset.coverage).coverageApproved=t.checked;if(t.name==='status-filter'){ui.filter=t.value;render();}if(t.name==='report-scope'){ui.reportJk=t.value;render();}if(t.name==='close-jk'){ui.closeJk=t.value;render();}if(t.name==='close-date'){ui.closeDate=t.value;render();}});
document.addEventListener('submit',e=>{const form=e.target;if(!form.dataset.form)return;e.preventDefault();const data=Object.fromEntries(new FormData(form)),kind=form.dataset.form;ui.error='';try{switch(kind){
case'login':{const a=ACCOUNTS[+data.account];if(a.role==='denied'){ui.denied=true;render();return;}session={...a};sessionStorage.setItem('ivc-session',JSON.stringify(session));ui.denied=false;nav('desk');break;}
case'search':ui.search=data.phone;search();break;
case'add-person':{if(digits(data.phone).length!==10)throw Error('Enter a 10-digit phone number.');const guardian=data.guardian==='yes';const p={id:uid('manual'),name:data.name.trim(),age:+data.age,phone:digits(data.phone),jk:data.jk,guardian,active:false,coc:false,team:guardian?'Guardian':'Service'};ui.custom.push(p);ui.results=ui.results||[];ui.results.push(p);ui.selected.push(p.id);$('#dialog').close();render();break;}
case'eligibility':{const id=form.dataset.id,kind=form.dataset.kind,p=getPeople().find(p=>p.id===id);if(kind==='active'&&digits(data.facilitatorPhone).length!==10)throw Error('Enter the facilitator’s 10-digit phone number.');const next=structuredClone(state);next.overrides[id]={...next.overrides[id],[kind==='coc'?'coc':'active']:true};const c=ctx();next.logs.push({id:uid('audit'),type:kind==='coc'?'COC completed at desk':'Facilitator confirmation',name:p.name,detail:kind==='coc'?'Event record only; master unchanged':data.facilitator+' · '+phone(data.facilitatorPhone),actor:c.actor,jk:c.jk,date:c.date,time:c.time});if(!persist(next))throw Error(storageProblem);ui.results=ui.results.map(p=>p.id===id?{...p,...state.overrides[id]}:p);$('#dialog').close();render();toast('Verification saved in the event’s demo activity log.');break;}
case'details':{const p=ui.draft[ui.current];Object.assign(p,data,{age:+data.age,size:data.size==='Choose a size'?'':data.size,phone:digits(data.phone),emergencyPhone:digits(data.emergencyPhone)});if(!p.size)throw Error('Choose a T-shirt size for '+p.name+'.');if(digits(p.phone).length!==10||digits(p.emergencyPhone).length!==10)throw Error('Enter 10-digit contact phone numbers.');if(p.age<=15&&!p.guardianId)throw Error('Choose an accompanying adult guardian.');if(ui.current<ui.draft.length-1){ui.current++;render();}else{const errors=validatePeople(ui.draft);if(errors.length)throw Error(errors[0]);ui.step=2;render();}break;}
case'child-sign':{const sig=saveSignature(form),p=ui.draft.find(p=>p.id===form.dataset.id);p.waiver='Signed';p.parentName=sig.name;p.signatureMethod=sig.method;p.signature=sig.signature;$('#dialog').close();render();break;}
case'parent-away':{if(digits(data.parentPhone).length!==10)throw Error('Enter a 10-digit parent phone number.');const p=ui.draft.find(p=>p.id===form.dataset.id);p.parentName=data.parentName.trim();p.parentPhone=digits(data.parentPhone);p.waiver='Waiting on parent';$('#dialog').close();render();break;}
case'cash':{const result=commitGroup(state,ui.draft,+data.cash,ctx());if(!persist(result.state))throw Error(storageProblem);ui.confirmation=result.ids;ui.step=0;ui.draft=[];ui.cash='';render();toast('Registrations saved.');break;}
case'collect':{const next=collectPayment(state,form.dataset.id,+data.cash,ctx());if(!persist(next))throw Error(storageProblem);$('#dialog').close();render();recordDialog(form.dataset.id);toast('Payment recorded using the original registration fee.');break;}
case'demo':{if(ui.step&&!confirm('Changing demo settings will discard the unsaved draft. Continue?'))return;session={...ACCOUNTS[+data.account],jk:data.jk};demoDate=data.demoDate;ui.closeDate=demoDate;ui.closeJk=data.jk;sessionStorage.setItem('ivc-session',JSON.stringify(session));sessionStorage.setItem('ivc-date',demoDate);ui.step=0;ui.draft=[];ui.confirmation=[];ui.results=null;ui.cash='';$('#dialog').close();render();break;}
case'close':{if(session.role==='desk')throw Error('Only admins can close cash.');const d=closeData(),counted=+data.counted,variance=Math.round((counted-d.expected)*100)/100;if(!Number.isFinite(counted)||counted<0)throw Error('Enter a valid cash count.');if(variance!==0&&!data.note.trim())throw Error('Explain the difference before recording this cash close.');if(!d.open.length&&d.closes.length)throw Error('All receipts for this day are already closed.');const next=structuredClone(state),c=ctx();next.closes.push({id:uid('close'),date:ui.closeDate,jk:d.jk,actor:c.actor,expected:d.expected,counted,variance,note:data.note.trim(),handedTo:data.handedTo.trim(),receiptIds:d.open.map(t=>t.id)});next.logs.push({id:uid('audit'),type:'Cash close',name:d.jk,actor:c.actor,jk:d.jk,date:ui.closeDate,time:c.time,detail:money(counted)+' handed to '+data.handedTo+'; variance '+money(variance)});if(!persist(next))throw Error(storageProblem);render();toast('Daily cash close recorded.');break;}
case'parent':{const sig=saveSignature(form),entry=readPublic(form.dataset.payload);if(!entry||entry.public.age>=18)throw Error('This parent link is not valid.');const next=structuredClone(state),r=next.registrations.find(r=>r.id===entry.public.id);if(r&&r.waiver!=='Signed'){r.waiver='Signed';r.parentName=sig.name;r.signatureMethod=sig.method;r.signature=sig.signature;next.logs.push({id:uid('audit'),type:'Parent waiver signed',name:r.name,actor:'Demo parent: '+sig.name,jk:r.deskJk,date:demoDate,time:new Date().toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'}),detail:sig.method+' signature from personal link'});if(!persist(next))throw Error(storageProblem);}localStorage.setItem('ivc-waiver-'+entry.public.id,JSON.stringify({name:sig.name,method:sig.method}));render();break;}
}}catch(err){if(form.closest('dialog'))dialogError(err.message);else{ui.error=err.message;const existing=form.querySelector('.form-error');if(existing)existing.remove();const div=document.createElement('div');div.className='notice error form-error';div.setAttribute('role','alert');div.textContent=err.message;form.prepend(div);div.tabIndex=-1;div.focus();}}});
function exportCsv(){const scope=session.role==='super'?ui.reportJk:session.jk,rows=aggregate(state,scope).rows;const columns=['Ticket ID','Name','Home JK','Desk JK','Age zone','Team','T-shirt','Guardian','Waiver','Payment','Fee','Registered on'];const values=rows.map(r=>[r.id,r.name,r.jk,r.deskJk,zoneFor(r.age),r.team,r.size,r.guardian?'Yes':'No',r.waiver,r.payment,r.fee,r.date]);const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const csv=[columns,...values].map(r=>r.map(cell).join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));a.download='ivc-2026-demo-registrations.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);toast('Demo registrations exported as CSV.');}
window.addEventListener('hashchange',()=>{if($('#dialog').open)$('#dialog').close();ui.error='';render();window.scrollTo(0,0);});
window.addEventListener('storage',e=>{if(e.key===KEY){state=readState();if(!ui.step){render();toast('Demo registration updated in another tab.');}}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#dialog').close();}});
persist();render();
